    inline constexpr std::uint64_t fnv1a64(const char* s)
    {
        std::uint64_t h = 0xCBF29CE484222325ULL;
        while (*s) { h ^= static_cast<std::uint8_t>(*s++); h *= 0x100000001B3ULL; }
        return h;
    }

    // Returns pointers to the recorded offsets, or nullptr.
    inline const std::uint16_t* lookup(const char* key, std::uint16_t& count)
    {
        const std::uint64_t h = fnv1a64(key);
        std::uint32_t lo = 0, hi = sizeof(kSpans) / sizeof(kSpans[0]);
        while (lo < hi) {
            const std::uint32_t mid = (lo + hi) / 2;
            if (kSpans[mid].hash < h) lo = mid + 1;
            else hi = mid;
        }
        if (lo >= sizeof(kSpans) / sizeof(kSpans[0]) || kSpans[lo].hash != h) return nullptr;
        count = kSpans[lo].count;
        return kOffsets + kSpans[lo].first;
    }
